// Generic Custom RGB Hook Factory
// 通用自定义 RGB Hook 工厂函数

/**
 * Factory function to create custom RGB hooks
 * 创建自定义 RGB hook 的工厂函数
 *
 * This eliminates code duplication between MSI and AyaNeo custom RGB hooks
 * 消除 MSI 和 AyaNeo 自定义 RGB hook 之间的代码重复
 */
function createCustomRgbHook(Setting, options) {
    return () => {
        const [presets, setPresets] = SP_REACT.useState(Setting.presets);
        const [editing, setEditing] = SP_REACT.useState(Setting.currentEditing);
        const [editingName, setEditingName] = SP_REACT.useState(Setting.currentEditingName);
        // Subscribe to changes
        SP_REACT.useEffect(() => {
            // Initialize and load presets from backend
            Setting.init();
            const unsubscribe = Setting.onPresetsChange(() => {
                setPresets({ ...Setting.presets });
                setEditing(Setting.currentEditing);
                setEditingName(Setting.currentEditingName);
            });
            return unsubscribe;
        }, []);
        /**
         * Update a specific zone color in a specific frame
         * 更新特定帧中特定区域的颜色
         */
        const updateZoneColor = (frameIdx, zoneIdx, color) => {
            if (!editing)
                return;
            const newConfig = JSON.parse(JSON.stringify(editing));
            newConfig.keyframes[frameIdx][zoneIdx] = color;
            // Support both updateEditingConfig (MSI) and updateEditing (AyaNeo)
            if (Setting.updateEditingConfig) {
                Setting.updateEditingConfig(newConfig);
            }
            else if (Setting.updateEditing) {
                Setting.updateEditing(newConfig);
            }
        };
        /**
         * Add a new keyframe (copy from current or default)
         * 添加新关键帧（从当前复制或使用默认）
         */
        const addKeyframe = (copyFrom) => {
            if (!editing || editing.keyframes.length >= options.maxKeyframes)
                return;
            // Determine zone count from first frame or use default
            const zoneCount = editing.keyframes[0]?.length || options.defaultZoneCount;
            const newConfig = { ...editing };
            if (copyFrom !== undefined && editing.keyframes[copyFrom]) {
                // Copy from specified frame
                newConfig.keyframes = [
                    ...newConfig.keyframes,
                    [...editing.keyframes[copyFrom]]
                ];
            }
            else {
                // Add default black frame with appropriate zone count
                newConfig.keyframes = [
                    ...newConfig.keyframes,
                    Array(zoneCount).fill([0, 0, 0])
                ];
            }
            if (Setting.updateEditingConfig) {
                Setting.updateEditingConfig(newConfig);
            }
            else if (Setting.updateEditing) {
                Setting.updateEditing(newConfig);
            }
        };
        /**
         * Delete a keyframe
         * 删除关键帧
         */
        const deleteKeyframe = (frameIdx) => {
            if (!editing || editing.keyframes.length <= 1)
                return;
            const newConfig = { ...editing };
            newConfig.keyframes = newConfig.keyframes.filter((_, idx) => idx !== frameIdx);
            if (Setting.updateEditingConfig) {
                Setting.updateEditingConfig(newConfig);
            }
            else if (Setting.updateEditing) {
                Setting.updateEditing(newConfig);
            }
        };
        /**
         * Update editing configuration (unified method)
         * 更新编辑配置（统一方法）
         */
        const updateConfig = (newConfig) => {
            if (!editing)
                return;
            if (Setting.updateEditingConfig) {
                Setting.updateEditingConfig(newConfig);
            }
            else if (Setting.updateEditing) {
                Setting.updateEditing(newConfig);
            }
        };
        /**
         * Update speed
         * 更新速度
         */
        const updateSpeed = (speed) => {
            if (!editing)
                return;
            updateConfig({ ...editing, speed });
        };
        /**
         * Update brightness
         * 更新亮度
         */
        const updateBrightness = (brightness) => {
            if (!editing)
                return;
            updateConfig({ ...editing, brightness });
        };
        /**
         * Preview current configuration on device
         * 在设备上预览当前配置
         */
        const preview = async () => {
            return await Setting.previewCurrent();
        };
        /**
         * Preview a single frame on device
         * 在设备上预览单个关键帧
         */
        const previewSingleFrame = async (frameIndex) => {
            return await Setting.previewSingleFrame(frameIndex);
        };
        /**
         * Save current configuration as a preset
         * 将当前配置保存为预设
         */
        const save = async (name) => {
            return await Setting.saveCurrent(name);
        };
        /**
         * Start editing a preset
         * 开始编辑预设
         */
        const startEditing = (name) => {
            Setting.startEditing(name);
        };
        /**
         * Cancel editing
         * 取消编辑
         */
        const cancelEditing = () => {
            Setting.cancelEditing();
        };
        /**
         * Delete a preset
         * 删除预设
         */
        const deletePreset = async (name) => {
            return await Setting.deletePreset(name);
        };
        /**
         * Apply a preset
         * 应用预设
         */
        const applyPreset = async (name) => {
            return await Setting.applyPreset(name);
        };
        return {
            // State
            presets,
            editing,
            editingName,
            // Editing operations
            updateZoneColor,
            addKeyframe,
            deleteKeyframe,
            updateSpeed,
            updateBrightness,
            updateConfig,
            // Actions
            preview,
            previewSingleFrame,
            save,
            startEditing,
            cancelEditing,
            deletePreset,
            applyPreset,
        };
    };
}

// Generic Custom RGB Setting Factory
// 通用自定义 RGB 设置工厂函数
