const SlowSliderField = (slider) => {
    const [changeValue, SetChangeValue] = SP_REACT.useState(slider.value);
    const isChanging = SP_REACT.useRef(false);
    SP_REACT.useEffect(() => {
        setTimeout(() => {
            //console.debug("changeValue=",changeValue,"slider=",slider.value)
            if (changeValue == slider.value) {
                slider.onChangeEnd?.call(slider, slider.value);
                isChanging.current = false;
            }
        }, 500);
    }, [changeValue]);
    return (window.SP_REACT.createElement(DFL.SliderField, { value: slider.value, label: slider.label, description: slider.description, min: slider.min, max: slider.max, step: slider.step, notchCount: slider.notchCount, notchLabels: slider.notchLabels, notchTicksVisible: slider.notchTicksVisible, showValue: slider.showValue, resetValue: slider.resetValue, disabled: slider.disabled, editableValue: slider.editableValue, validValues: slider.validValues, valueSuffix: slider.valueSuffix, minimumDpadGranularity: slider.minimumDpadGranularity, className: slider.className, onChange: (value) => {
            var tpvalue = value;
            if (slider.changeMax != undefined)
                tpvalue = slider.changeMax <= value ? slider.changeMax : value;
            if (slider.changeMin != undefined)
                tpvalue = slider.changeMin >= value ? slider.changeMin : value;
            isChanging.current = true;
            slider.onChange?.call(slider, tpvalue);
            slider.value = tpvalue;
            SetChangeValue(tpvalue);
        } }));
};

const SuspendModeComponent = () => {
    const [suspendMode, setSuspendMode] = SP_REACT.useState(Setting.suspendMode);
    const [isSupportSuspendMode] = SP_REACT.useState(Setting.isSupportSuspendMode);
    const options = [
        { mode: SuspendMode.OEM, label: localizationManager.getString(localizeStrEnum.SUSPEND_MODE_OEM) },
        { mode: SuspendMode.KEEP, label: localizationManager.getString(localizeStrEnum.SUSPEND_MODE_KEEP) },
        { mode: SuspendMode.OFF, label: localizationManager.getString(localizeStrEnum.SUSPEND_MODE_OFF) },
    ];
    const modeToNumber = (mode) => {
        return options.findIndex((option) => option.mode === mode);
    };
    const numberToMode = (number) => {
        return options[number].mode || SuspendMode.OEM;
    };
    const ledModeLabels = options.map((option, idx) => {
        return {
            notchIndex: idx,
            label: option.label,
            value: modeToNumber(option.mode),
        };
    });
    const updateMode = (mode) => {
        setSuspendMode(numberToMode(mode));
    };
    SP_REACT.useEffect(() => {
        Logger.info(`HueSync: suspendMode: ${suspendMode}`);
        // Only update if new value is not empty and different from current
        // 只有当新值不为空且与当前值不同时才更新
        if (Setting.suspendMode !== suspendMode && suspendMode !== "") {
            Logger.info(`HueSync: updating suspend mode from '${Setting.suspendMode}' to '${suspendMode}'`);
            Setting.suspendMode = suspendMode;
        }
        else if (suspendMode === "") {
            Logger.warn(`HueSync: ignoring empty suspend mode value`);
        }
    }, [suspendMode]);
    return (window.SP_REACT.createElement(window.SP_REACT.Fragment, null, isSupportSuspendMode && window.SP_REACT.createElement(DFL.PanelSectionRow, null,
        window.SP_REACT.createElement(SlowSliderField, { label: localizationManager.getString(localizeStrEnum.SUSPEND_MODE), description: localizationManager.getString(localizeStrEnum.SUSPEND_MODE_DESC), value: modeToNumber(suspendMode), min: 0, max: ledModeLabels.length - 1, step: 1, notchCount: ledModeLabels.length, notchLabels: ledModeLabels, notchTicksVisible: true, showValue: false, onChange: updateMode }))));
};

const ActionButtonItem = (props) => {
    const { onClick, disabled, children, loading, layout, debugLabel } = props;
    const [_loading, setLoading] = SP_REACT.useState(loading);
    const handClick = async (event, onClick) => {
        try {
            console.log(`ActionButtonItem: ${debugLabel}`);
            setLoading(true);
            await onClick?.(event);
            console.log(`ActionButtonItem: ${debugLabel} done`);
        }
        catch (e) {
            console.error(`ActionButtonItem error: ${e}`);
        }
        finally {
            // console.log(`ActionButtonItem: ${debugLabel} disable loading`);
            setLoading(false);
        }
    };
    const isLoading = _loading;
    return (window.SP_REACT.createElement(DFL.ButtonItem, { ...props, layout: layout ?? "below", disabled: isLoading || disabled, onClick: (e) => handClick(e, onClick) },
        window.SP_REACT.createElement("span", { style: { display: 'flex', justifyContent: 'center', alignItems: 'center' } },
            children,
            " ",
            isLoading && window.SP_REACT.createElement(DFL.Spinner, { style: { margin: '0px 8px', width: '1.1em' } }))));
};

const SpeedControl = ({ speed, onChange }) => {
    // Map string to number: "low" -> 0, "medium" -> 1, "high" -> 2
    const speedToValue = (speedStr) => {
        const map = { low: 0, medium: 1, high: 2 };
        return map[speedStr] ?? 1;
    };
    // Map number to string: 0 -> "low", 1 -> "medium", 2 -> "high"
    const valueToSpeed = (value) => {
        const map = { 0: "low", 1: "medium", 2: "high" };
        return map[value] ?? "medium";
    };
    return (window.SP_REACT.createElement(SlowSliderField, { label: localizationManager.getString(localizeStrEnum.SPEED),
        // description={localizationManager.getString(localizeStrEnum.SPEED_DESC)}
        value: speedToValue(speed), min: 0, max: 2, step: 1, notchCount: 3, notchLabels: [
            {
                notchIndex: 0,
                label: localizationManager.getString(localizeStrEnum.SPEED_LOW),
                value: 0,
            },
            {
                notchIndex: 1,
                label: localizationManager.getString(localizeStrEnum.SPEED_MEDIUM),
                value: 1,
            },
            {
                notchIndex: 2,
                label: localizationManager.getString(localizeStrEnum.SPEED_HIGH),
                value: 2,
            },
        ], notchTicksVisible: true, showValue: false, onChange: (value) => {
            onChange(valueToSpeed(value));
        }, onChangeEnd: (value) => {
            onChange(valueToSpeed(value));
        } }));
};

